    ell(ctx, cx, top + T*.06, w, T*.07, N ? '#b4cce0' : '#e8f4fc'); ell(ctx, cx + w*.1, top + T*.07, w*.6, T*.035, N ? '#6a88a4' : '#a8c8e0'); // its broken top
    ctx.fillStyle = 'rgba(230,244,255,.7)'; for (let i=0;i<4;i++){ const dx = cx - w + i*w*.66; ctx.beginPath(); ctx.moveTo(dx - 2, bot - T*.01); ctx.lineTo(dx + 2, bot - T*.01); ctx.lineTo(dx + T*.02, bot + T*.05); ctx.fill(); }
